package shape

import (
	"strings"
	"testing"
	"time"
)

func TestBudgetStopReportsSubmissionTruthfully(t *testing.T) {
	w := responsesWire
	for _, submitted := range []bool{true, false} {
		name := "no submission"
		steps := []shpStep{w.readReadme("r1"), w.readReadme("r2")}
		if submitted {
			name = "two refused submissions"
			bad := func(p string) shpStep {
				return w.shapeSubmit(p, map[string]any{"files": []any{map[string]any{"path": p, "content": "x\n"}}})
			}
			steps = []shpStep{bad("first.go"), bad("second.go")}
		}
		t.Run(name, func(t *testing.T) {
			f := budgetFx(t, 8*time.Minute, steps...)
			exit, err := f.shape("Bound shaping.")
			e := shpWantError(t, err, "shape", "invalid_output", "15-minute", 1)
			shpEq(t, "exit", exit, 1)
			text := strings.Join(e.Lines, "\n")
			shpEq(t, "no-submit line", strings.Contains(text, "the shaper ended without calling submit"), !submitted)
			if submitted {
				for _, want := range []string{
					"last refusal (attempt 2, gate validation):",
					"earliest unresolved refusal (attempt 1, gate validation):",
					"attempt 1: gate validation, model request 480 s, Kogen checks 0 s, 420 s remaining",
					"attempt 2: gate validation, model request 480 s, Kogen checks 0 s, 0 s remaining",
				} {
					shpContains(t, "refusal", text, want)
				}
			}
			shpContains(t, "refusal", text, budgetFigureLine)
			shpEq(t, "requests", len(f.Prov.requests()), 2)
		})
	}
}

